=IFERROR(__xludf.DUMMYFUNCTION("{""STT"",""Devices"",""Price Base"";
ARRAYFORMULA(
  LET(
    data,
    UNIQUE(
      HSTACK(
        FILTER(
          AP_input!B:B,
          AP_input!A:A<>"""",
          REGEXMATCH(TO_TEXT(AP_input!A:A),""^\d+(\.0)?$"")
        ),
        FILTER(
    "&"      AP_input!N:N,
          TRIM(AP_input!M:M)=""SubTotal""
        )
      )
    ),
    HSTACK(
      SEQUENCE(ROWS(data)),
      INDEX(data,,1),
      INDEX(data,,2)
    )
  )
)}"),"STT")

=IFERROR(__xludf.DUMMYFUNCTION("{""License"",""List Price"";
ARRAYFORMULA(
IFERROR(
UNIQUE(
FILTER(
HSTACK(
AP_input!B:B,
AP_input!N:N
),
REGEXMATCH(TO_TEXT(AP_input!A:A),""^\d+\.\d+$""),
REGEXMATCH(
IFNA(
VLOOKUP(
VALUE(REGEXEXTRACT(TO_TEXT(AP_input!A:A),""^\d+"")),
HSTACK(
VALUE(AP_in"&"put!A:A),
AP_input!B:B
),
2,
FALSE
),
""""
),
""^(CISCO-NETWORK-SUB)$""
)
)
),
""""
)
)}"),"License")

